 const pmrem=new T.PMREMGenerator(renderer),environment=new RoomEnvironment();const env=pmrem.fromScene(environment,.04);scene.environment=env.texture;environment.dispose();pmrem.dispose();
 scene.add(new T.HemisphereLight(0xe4efff,0x424654,.8));const light=new T.DirectionalLight(0xffffff,1.6);light.position.set(4,7,-3);scene.add(light);
 const ground=new T.Mesh(new T.CircleGeometry(8,64),new T.MeshStandardMaterial({color:0x171f2b,roughness:.65,metalness:.15}));ground.rotation.x=-Math.PI/2;ground.position.y=-.02;scene.add(ground);const wallMaterial=new T.MeshStandardMaterial({color:0x202731,roughness:.85});for(const [x,z,w,d]of [[0,4,16,.2],[-6,0,.2,12],[6,0,.2,12]]){const wall=new T.Mesh(new T.BoxGeometry(w,5,d),wallMaterial);wall.position.set(x,2.5,z);scene.add(wall);}new T.TextureLoader().load('/assets/logo.png',texture=>{const logo=new T.Mesh(new T.PlaneGeometry(2.4,2.4),new T.MeshBasicMaterial({map:texture,transparent:true}));logo.position.set(0,2.4,3.85);logo.rotation.y=Math.PI;scene.add(logo);});for(const x of [-4,0,4]){const strip=new T.Mesh(new T.BoxGeometry(2.6,.035,.18),new T.MeshBasicMaterial({color:0xe8f2ff}));strip.position.set(x,4.7,0);scene.add(strip);} 
 const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.65,0);controls.minDistance=3;controls.maxDistance=10;controls.maxPolarAngle=Math.PI/2-.02;controls.enablePan=false;controls.enableDamping=true;controls.autoRotate=!matchMedia('(prefers-reduced-motion: reduce)').matches;controls.autoRotateSpeed=.6;
